arguments.query:
query PlayNexusGraphSmoke {
  graphInfo {
    name
    version
    readOnly
    introspection
    entities
    maxDepth
    maxComplexity
    maxFields
    maxPageSize
  }
  stats {
    games
    activeGames
    studios
    brands
    platforms
    products
    publishedProducts
    content
    publishedContent
    collections
    publicCollections
    categories
    gameEvents
    activeGameEvents
    sourceStates
  }
  games(first: 3, status: "active", orderBy: "id", orderDir: "desc") {
    nodes {
      id
      name
      slug
      status
      releaseDate
      studio {
        id
        name
        slug
        status
      }
      platforms {
        id
        name
        slug
        status
      }
      products(first: 2, status: "published", visibility: "public") {
        nodes {
          id
          title
          slug
          status
          visibility
          price
          platforms {
            id
            name
            slug
          }
        }
        pageInfo {
          total
          first
          offset
          hasMore
          nextOffset
        }
      }
      content(first: 2, status: "published") {
        nodes {
          id
          type
          title
          slug
          status
          publishedAt
          relatedProduct {
            id
            title
            slug
          }
          media {
            id
            type
            url
            alt
          }
        }
        pageInfo {
          total
          first
          offset
          hasMore
          nextOffset
        }
      }
    }
    pageInfo {
      total
      first
      offset
      hasMore
      nextOffset
    }
  }
}
